// === SESSION FAILURE LOG — Grouped Failure Analysis ===\n
// Reads .session-log.jsonl and reports WHY sessions fail\n
// CLI: node .fastops/session-failure-log.js --report\n\n
const fs = require('fs');
const path = require('path');

const LOG_FILE = path.join(__dirname, '.session-log.jsonl');

function readLog() {
  return fs.readFileSync(LOG_FILE, 'utf-8')
    .split('\n')
    .filter(line => line.trim())
    .map(line => JSON.parse(line));
}

function groupFailures(entries) {
  const failures = {
    status_change: {},
    turn_failures: {}
  };

  entries.forEach(entry => {
    if (entry.event === 'status_change' &&
        (entry.status === 'failed' || entry.status === 'max_turns')) {
      const reason = entry.status;
      failures.status_change[reason] = failures.status_change[reason] || { count: 0, sessions: [] };
      failures.status_change[reason].count++;
      failures.status_change[reason].sessions.push(entry.sessionId);
      if (failures.status_change[reason].sessions.length > 3) {
        failures.status_change[reason].sessions.shift();
      }
    }

    if (entry.event === 'turn' && entry.success === false) {
      const reason = entry.actions?.join(',') || 'unknown_actions';
      failures.turn_failures[reason] = failures.turn_failures[reason] || { count: 0, sessions: [] };
      failures.turn_failures[reason].count++;
      failures.turn_failures[reason].sessions.push(entry.sessionId);
      if (failures.turn_failures[reason].sessions.length > 3) {
        failures.turn_failures[reason].sessions.shift();
      }
    }
  });

  return failures;
}

function printReport(failures) {
  console.log('=== SESSION FAILURE ANALYSIS ===');
  console.log('\n[STATUS CHANGE FAILURES]');
  Object.entries(failures.status_change).forEach(([reason, data]) => {
    console.log(`- ${reason}: ${data.count} (last 3: ${data.sessions.join(', ')})`);
  });

  console.log('\n[TURN-LEVEL FAILURES]');
  Object.entries(failures.turn_failures).forEach(([reason, data]) => {
    console.log(`- ${reason}: ${data.count} (last 3: ${data.sessions.join(', ')})`);
  });
}

if (require.main === module) {
  if (process.argv.includes('--report')) {
    const entries = readLog();
    const failures = groupFailures(entries);
    printReport(failures);
  }
}

module.exports = { readLog, groupFailures, printReport };
